<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserEmailVerifiedAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserEmailVerifiedAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserEmailVerifiedAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isEmailVerified returns null on a freshly created holder.
     */
    public function testEmailVerifiedNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailVerifiedAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isEmailVerifiedAssigned());
        $this->assertNull($holder->isEmailVerified());
    }
}
class ImplWithUserEmailVerifiedAttributeHolderUnitTest
{
    use UserEmailVerifiedAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedEmailVerifiedRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultEmailVerified();
    }
}
